def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    prev_bids = []
    desperate_count = 0
    rich_aggressive = 0

    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            if opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 1:
                desperate_count += 1
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                bid = float(prev['bid'])
                prev_bids.append(bid)
                if bid >= 120 and opp.get('budget', 0) >= 120:
                    rich_aggressive += 1

    if not alive:
        return float(min(budget, 18.0))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    tight_supply = supply <= 17
    loose_supply = supply >= 22

    urgency = 0
    if hp <= 2:
        urgency += 3
    elif hp <= 4:
        urgency += 2
    elif hp <= 6:
        urgency += 1

    if no_water_days >= 2:
        urgency += 3
    elif no_water_days >= 1:
        urgency += 2

    if tight_supply:
        urgency += 2
    elif not loose_supply:
        urgency += 1

    if desperate_count >= 2:
        urgency += 1

    if day >= 8:
        urgency += 1

    if urgency >= 6:
        target = max(95.0, highest_prev + 6.0)
    elif urgency >= 4:
        target = max(62.0, avg_prev + 4.0, highest_prev * 0.72)
    elif urgency >= 2:
        target = max(34.0, avg_prev * 0.45 + 8.0)
    else:
        target = 16.0 if loose_supply else 22.0

    if rich_aggressive >= 2 and hp > 4 and no_water_days == 0:
        target *= 0.72
    elif rich_aggressive >= 1 and hp > 5 and loose_supply:
        target *= 0.82

    reserve_days = max(0, 10 - day)
    soft_cap = budget / max(1, reserve_days)
    if urgency <= 2:
        cap = max(22.0, soft_cap * 0.9)
    elif urgency <= 4:
        cap = max(45.0, soft_cap * 1.35)
    else:
        cap = max(70.0, soft_cap * 2.4)

    bid = min(target, cap, budget)

    if hp <= 2 or no_water_days >= 2:
        bid = min(budget, max(bid, 105.0, highest_prev + 3.0))
    elif hp <= 4 or no_water_days >= 1:
        bid = min(budget, max(bid, 72.0))

    if budget < 25:
        bid = budget

    if bid < 0:
        bid = 0.0

    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    my_hp = float(my_status.get('hp', 0.0))
    my_budget = float(my_status.get('budget', 0.0))
    my_no_water_days = int(my_status.get('no_water_days', 0))

    alive_opps = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opps.append(opp)

    if not alive_opps:
        return max(0.0, min(my_budget, DAILY_SALARY * 0.4))

    # Read yesterday bids from immediate previous_trace only
    yesterday_bids = []
    for opp in alive_opps:
        prev = opp.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                yesterday_bids.append(float(b))
            except Exception:
                pass

    highest_prev_bid = max(yesterday_bids) if yesterday_bids else 0.0
    avg_prev_bid = (sum(yesterday_bids) / len(yesterday_bids)) if yesterday_bids else 0.0

    # Estimate how many full water units might be available
    # (supply is total pot; water requirement per player is WATER_REQ)
    # Use int indices safely by converting to ints where needed.
    supply_units = int(supply // float(WATER_REQ))
    if supply_units < 1:
        supply_units = 1

    # Core strategy: avoid matching the top bidders unless we're in danger.
    # Typical observed meta: many bids cluster around 120-150 with supply 15-25.
    # We'll target slightly below the average, but above a baseline.
    baseline = DAILY_SALARY * 0.55

    # If opponents were bidding extremely high yesterday, increase to avoid being outbid.
    if highest_prev_bid >= DAILY_SALARY * 0.85 or avg_prev_bid >= DAILY_SALARY * 0.75:
        danger_factor = 1.0
        if my_hp <= 2.5:
            danger_factor = 1.25
        elif my_hp <= 4.0:
            danger_factor = 1.12
        else:
            danger_factor = 1.05
        target = max(baseline, avg_prev_bid * 0.92) * danger_factor
    else:
        # If yesterday wasn't a bidding frenzy, bid around baseline but scale with our HP.
        if my_hp <= 2.5 or my_no_water_days >= 2:
            target = max(baseline * 1.2, avg_prev_bid * 0.9)
        elif my_hp <= 4.0:
            target = max(baseline * 1.05, avg_prev_bid * 0.85)
        else:
            # Healthy: bid just enough to compete.
            # Also slightly adjust with supply units (more supply => can bid less).
            supply_adjust = 1.0
            if supply_units >= 2:
                supply_adjust = 0.95
            elif supply_units <= 1:
                supply_adjust = 1.05
            target = baseline * supply_adjust

    # Ensure we don't exceed budget and keep within plausible range.
    # If budget is low, spend most of it when HP is critical.
    if my_budget <= 0:
        return 0.0

    if my_hp <= 1.5:
        bid = my_budget * 0.95
    elif my_hp <= 3.0:
        bid = min(my_budget, target * 1.05)
    else:
        bid = min(my_budget, target)

    # Hard cap to avoid irrational overspending beyond a day's salary scale.
    bid_cap = DAILY_SALARY * 1.2
    bid = min(bid, bid_cap)

    # Final safety
    if bid < 0.0:
        bid = 0.0
    return float(bid)

